/**
 * auto = derive from percent of ideal days; manual = pinned value.
 */
export type GraceCellMode = typeof GraceCellMode[keyof typeof GraceCellMode];


export const GraceCellMode = {
  auto: 'auto',
  manual: 'manual',
} as const;

/**
 * One grace band cell. MANUAL pins a typed `value` (days); AUTO derives the grace from `percent` of THIS activity's own ideal days (effective = round(percent/100 * idealDays)). `mode` decides which is effective; both fields may be present so toggling auto<->manual remembers the last percentage/value.

 */
export interface GraceCell {
  /** auto = derive from percent of ideal days; manual = pinned value. */
  mode: GraceCellMode;
  /** AUTO only — percent of this activity's ideal days. */
  percent?: number;
  /** MANUAL only — pinned grace days (overrun beyond the cumulative target). */
  value?: number;
}

/**
 * Three escalating PRE-WARNING thresholds, each a PERCENT of the activity's cumulative target consumed (consumed = ageing / cumulativeTarget). They apply only while a mark is still WITHIN target; once exceeded the grace bands take over. After resolution 0 <= pw1 <= pw2 <= pw3 <= 100.

 */
export interface PreWarnConfig {
  /** First pre-warning threshold (percent of target consumed). */
  pw1: number;
  /** Second pre-warning threshold (percent of target consumed). */
  pw2: number;
  /** Third pre-warning threshold (percent of target consumed). */
  pw3: number;
}

/**
 * Sparse per-project pre-warning override; any subset of pw1/pw2/pw3. A present field replaces the global; an absent field inherits the global.

 */
export interface PartialPreWarnConfig {
  pw1?: number;
  pw2?: number;
  pw3?: number;
}

/**
 * Per-activity turnaround configuration. idealDays feeds the cumulative target; yellow/orange/red are grace-band CELLS (auto/manual). Resolved effective grace is validated non-negative with yellow <= orange <= red. preWarn holds the within-target pre-warning percentage thresholds.

 */
export interface ActivityConfig {
  /** Ideal days for this single activity (feeds the cumulative target). */
  idealDays: number;
  yellow: GraceCell;
  orange: GraceCell;
  red: GraceCell;
  preWarn: PreWarnConfig;
}

/**
 * Sparse per-project override of any subset of {idealDays, yellow/orange/red cell, preWarn}. Any field present REPLACES the global value for that (project, activity); any field absent INHERITS the global value (per cell). All fields optional.

 */
export interface PartialActivityConfig {
  /** Override ideal days for this activity (feeds the cumulative target). */
  idealDays?: number;
  yellow?: GraceCell;
  orange?: GraceCell;
  red?: GraceCell;
  preWarn?: PartialPreWarnConfig;
}

/**
 * Global ("All Sections") per-activity config for this NTLT category.
 */
export type CategorySettingsActivities = {[key: string]: ActivityConfig};

/**
 * Sparse per-section overrides keyed by section (group_key) then activity code. Only overridden cells/fields are stored.

 */
export type CategorySettingsPerSection = {[key: string]: {[key: string]: PartialActivityConfig}};

/**
 * One NTLT category's turnaround config: a global ("All Sections") per-activity map keyed by THIS category's sequence activity codes, plus optional sparse per-SECTION overrides (the NTLT analogue of activities + perProject). TLT stays at the top level of TurnaroundSettings.

 */
export interface CategorySettings {
  /** Global ("All Sections") per-activity config for this NTLT category. */
  activities: CategorySettingsActivities;
  /** Sparse per-section overrides keyed by section (group_key) then activity code. Only overridden cells/fields are stored.
   */
  perSection?: CategorySettingsPerSection;
}

